edges = set()

# 14-cycle
for i in range(n):
    edges.add((i, (i+1) % n))

# chords at distance 7
for i in range(n):
    j = (i + 7) % n
    if i < j:
        edges.add((i, j))

print(f"Number of edges: {len(edges)}")
print(f"Edges: {sorted(edges)}")

# Check girth
from collections import defaultdict, deque

adj = defaultdict(set)
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# BFS from each vertex to find shortest cycle
def shortest_cycle(start):
    dist = {start: 0}
    parent = {start: -1}
    q = deque([start])
    min_cycle = float('inf')

    while q:
        v = q.popleft()
        for u in adj[v]:
            if u == parent[v]:
                continue
            if u in dist:
                # Found a cycle
                cycle_len = dist[v] + dist[u] + 1
                if cycle_len < min_cycle:
                    min_cycle = cycle_len
            else:
                dist[u] = dist[v] + 1
                parent[u] = v
                q.append(u)
    return min_cycle

min_girth = float('inf')
for v in range(n):
    g = shortest_cycle(v)
    if g < min_girth:
        min_girth = g

print(f"Girth: {min_girth}")

