from collections import defaultdict

n = 14
edges = set()
for i in range(n):
    edges.add((i, (i+1) % n))

# Try chords at 0, 3, 6 (all distance 3 apart)
for i in [0, 3, 6]:
    edges.add((i, i+7))

adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Find all cycles up to length 10
def find_cycles(start, max_len=10):
    cycles = []
    def dfs(v, visited, path):
        if len(path) > max_len:
            return
        for u in adj[v]:
            if u == start and len(path) >= 3:
                cycles.append(path + [u])
            elif u not in visited and u > start:  # avoid duplicates
                dfs(u, visited | {u}, path + [u])
    dfs(start, {start}, [start])
    return cycles

for v in range(n):
    cycles = find_cycles(v, 10)
    for c in cycles:
        if len(c) - 1 < 8:  # len(c)-1 is cycle length
            print(f"Short cycle: {c}, length={len(c)-1}")

# Let me also check girth properly
def shortest_cycle_bfs(start):
    dist = {start: 0}
    parent = {start: -1}
    q = [start]
    min_cycle = float('inf')
    for v in q:
        for u in adj[v]:
            if u == parent.get(v, -1):
                continue
            if u in dist:
                cycle_len = dist[v] + dist[u] + 1
                if cycle_len < min_cycle:
                    min_cycle = cycle_len
            else:
                dist[u] = dist[v] + 1
                parent[u] = v
                q.append(u)
    return min_cycle

min_g = float('inf')
for v in range(n):
    g = shortest_cycle_bfs(v)
    if g < min_g:
        min_g = g
print(f"Girth: {min_g}")
